grid=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and (r,c) not in seen:
   st=[(r,c)]; seen.add((r,c)); comp=[]
   while st:
    p=st.pop(); comp.append(p)
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
     q=(p[0]+dr,p[1]+dc)
     if 0<=q[0]<R and 0<=q[1]<C and grid[q[0]][q[1]]==0 and q not in seen: seen.add(q);st.append(q)
   comps.append(comp)
[(len(x), min(r for r,c in x), max(r for r,c in x), min(c for r,c in x), max(c for r,c in x), sorted(x)) for x in comps]
